import{_ as i,C as n,o as a,c as o,ah as s,E as r}from"./chunks/framework.sPHStHqt.js";const m=JSON.parse('{"title":"Subscribers","description":"","frontmatter":{},"headers":[],"relativePath":"subscriptions/subscribers.md","filePath":"subscriptions/subscribers.md","lastUpdated":1789630599000}'),l={name:"subscriptions/subscribers.md"};function c(b,e,h,u,p,d){const t=n("ImagePopup");return a(),o("div",null,[e[0]||(e[0]=s('<h1 id="subscribers" tabindex="-1">Subscribers <a class="header-anchor" href="#subscribers" aria-label="Permalink to &quot;Subscribers&quot;">​</a></h1><p>Once a tenant is on a paid plan, they become a <strong>subscriber</strong>. This screen is the operator&#39;s view of everyone currently paying — who is on which plan, when their cycle renews, and whether they&#39;ve lapsed.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to read the subscriber list</li><li>What a subscriber&#39;s detail view shows</li><li>How to re-send an invoice to a subscriber</li></ul></div><h2 id="the-subscriber-list" tabindex="-1">The subscriber list <a class="header-anchor" href="#the-subscriber-list" aria-label="Permalink to &quot;The subscriber list&quot;">​</a></h2><p>Open <strong>Subscription → Subscribers</strong>.</p>',5)),r(t,{src:"/images/subscribers/subscribers-grid.png",alt:"Subscribers list"}),e[1]||(e[1]=s('<p>Each row is one tenant on a paid plan:</p><ul><li><strong>Name</strong> — the subscribing company.</li><li><strong>Email</strong> — the account address.</li><li><strong>Domain</strong> — the tenant&#39;s CRM address.</li><li><strong>Status</strong> — <strong>Active</strong> or <strong>Inactive</strong>, mirroring whether the tenant account itself is enabled.</li><li><strong>Is Expired</strong> — flags a subscriber whose billing cycle has run out.</li><li><strong>Plan Name</strong> — the plan they&#39;re on.</li><li><strong>Plan Validity / Remaining Days</strong> — the billing cycle (monthly or yearly) followed by how many days are left before it renews.</li><li><strong>Plan Renewal On</strong> — the date the current cycle ends and the next payment is due.</li><li><strong>Plan Amount</strong> — what they pay for the cycle.</li><li><strong>Created At</strong> — when the subscription started.</li></ul><p>Use <strong>Search</strong> to find a subscriber by name or email, and <strong>Filter</strong> to narrow by status.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Only paid subscriptions appear here. Tenants still on a free trial are not subscribers yet — they show up once they choose and pay for a plan. See <a href="/subscriptions/trials">Free Trials</a>.</p></div><h2 id="a-subscriber-s-detail-view" tabindex="-1">A subscriber&#39;s detail view <a class="header-anchor" href="#a-subscriber-s-detail-view" aria-label="Permalink to &quot;A subscriber&#39;s detail view&quot;">​</a></h2><p>Select a row to open the subscriber&#39;s detail view.</p>',6)),r(t,{src:"/images/subscribers/subscriber-view.png",alt:"Subscriber detail view"}),e[2]||(e[2]=s('<p>It restates the company&#39;s details — <strong>Company Name</strong>, <strong>Email</strong>, <strong>Username</strong>, <strong>Domain</strong> and <strong>Status</strong> — alongside the subscription itself: the <strong>Plan Name</strong>, <strong>Plan Amount</strong>, <strong>Plan Validity</strong> (the renewal date) and <strong>Remaining Days</strong> in the current cycle.</p><h2 id="re-sending-an-invoice" tabindex="-1">Re-sending an invoice <a class="header-anchor" href="#re-sending-an-invoice" aria-label="Permalink to &quot;Re-sending an invoice&quot;">​</a></h2><p>The <strong>Send Invoice</strong> button at the top of the detail view e-mails the subscriber their most recent active invoice again — useful if the tenant misplaced it or asks for a copy for their records.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This sends the <em>existing</em> invoice for the current cycle; it does not charge the tenant again or create a new invoice. Every invoice ever raised is listed on <a href="/subscriptions/invoices">Invoices</a>.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Browse the invoices behind these subscriptions → <a href="/subscriptions/invoices">Invoices</a></li><li>See how a tenant picks a plan in the first place → <a href="/tenants/choosing-a-plan">Choosing a Plan</a></li><li>Build or adjust the plans they subscribe to → <a href="/subscriptions/plan-management">Plan Management</a></li></ul>',6))])}const _=i(l,[["render",c]]);export{m as __pageData,_ as default};
